<script>
import Papa from "papaparse";
export default {
  created: function () {
    this.parseFile();
  },
  methods: {
    parseFile() {
      Papa.parse(this.raw, {
        header: true,
        skipEmptyLines: true,
        complete: (results) => {
          this.content = results;
        },
      });
    },
    extractICAO(value) {
      return value.includes("-") ? value.split("-")[0] : value;
    },
    getAirlineName(value) {
      if (!value.includes("-")) {
        return this.airlines[value.slice(0, 3)];
      } else {
        return this.airlines[value.split("-")[1].slice(0, 3)];
      }
    },
    toggleSortByColumn(column) {
      if (this.sortBy === column) {
        this.sortOrder = this.sortOrder === "asc" ? "desc" : "asc";
      } else {
        this.sortBy = column;
        this.sortOrder = "desc";
      }
    },
    getSortIcon(column) {
      if (this.sortBy === column) {
        return require(`@/assets/icons/arrow-${this.sortOrder}.svg`);
      }
      return require("@/assets/icons/arrow-down-up.svg");
    },
    goToPage(page) {
      if (page >= 1 && page <= this.totalPages) {
        this.currentPage = page;
      }
    },
    getImageUrlFull(row) {
      return `https://cdn.jetphotos.com/full${
        row["Registration"].split("|")[2]
      }`;
    },
  },
  mounted() {
    document.title = "Weili: Flight Log";
    window.scrollTo({
      top: 0,
      behavior: "smooth",
    });
  },
  computed: {
    sortedData() {
      // creates copy this.content.data
      const data = [...this.content.data];
      if (this.sortBy == "Date") {
        return this.sortOrder === "desc"
          ? this.content.data
          : [...this.content.data].reverse();
      } else if (this.sortBy == "Miles") {
        data.sort((a, b) => {
          const valA = parseInt(a[this.sortBy]) || 0;
          const valB = parseInt(b[this.sortBy]) || 0;
          return this.sortOrder === "asc" ? valA - valB : valB - valA;
        });
      } else {
        data.sort((a, b) => {
          const valA = (a[this.sortBy] || "").toString().toLowerCase();
          const valB = (b[this.sortBy] || "").toString().toLowerCase();
          if (valA < valB) return this.sortOrder === "asc" ? -1 : 1;
          if (valA > valB) return this.sortOrder === "asc" ? 1 : -1;
          return 0;
        });
      }
      return data;
    },
    paginatedData() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.sortedData.slice(start, end);
    },
  },
  watch: {
    isGalleryView(val) {
      if (val) {
        this.sortBy = "Date";
        this.sortOrder = "desc";
      }
    },
  },
