    const sortableCols = [
      "Date",
      "Miles",
      "Airline",
      "Aircraft",
      "Flight",
      "Registration",
    ];
    const raw = atob(blob);
    return {
      raw: raw,
      content: content,
      airlines: airlines,
      airports: airports,
      currentPage: 1,
